@inlinable public func simd_double(_ x: simd_long8) -> simd_double8 { convertIntegerToFloat(x) }
@inlinable public func simd_double(_ x: simd_ulong8) -> simd_double8 { convertIntegerToFloat(x) }
@inlinable public func simd_double(_ x: simd_float8) -> simd_double8 { convertFloatToFloat(x) }
@inlinable public func simd_double(_ x: simd_double8) -> simd_double8 { convertFloatToFloat(x) }

